const reply=(data,status=200,extra={})=>Response.json(data,{status,headers:{'Cache-Control':'private,no-store','Referrer-Policy':'no-referrer',...extra}});
const hex=/^[a-f0-9]{64}$/;const keys=(v,allowed)=>v&&typeof v==='object'&&!Array.isArray(v)&&Object.keys(v).every(k=>allowed.includes(k));
const digest=async s=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s))),b=>b.toString(16).padStart(2,'0')).join('');
function validCopy(v){return keys(v,['label','date','type','language','currentLanguage','items'])&&typeof v.label==='string'&&v.label.length<=160&&(v.date===null||typeof v.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v.date))&&(v.type===null||['debrief','gpa','other'].includes(v.type))&&typeof v.language==='string'&&v.language.length>0&&v.language.length<=60&&['sq','en'].includes(v.currentLanguage)&&Array.isArray(v.items)&&v.items.length>0&&v.items.length<=31&&v.items.every(x=>keys(x,['label','text'])&&typeof x.label==='string'&&x.label.length<=160&&typeof x.text==='string'&&x.text.length<=30000);}

function validPortalCopy(v){if(!keys(v,['label','date','type','language','currentLanguage','items','sharedByName'])||typeof v.sharedByName!=='string'||!v.sharedByName.trim()||v.sharedByName.length>120)return false;const {sharedByName,...base}=v;return validCopy(base);}
async function portalCommand(req,env){
 const raw=await req.text();if(raw.length>150000)return reply({error:'invalid'},400);
 const signature=req.headers.get('x-command-signature');if(!signature)return reply({error:'unauthorized'},401);
 let bytes;try{bytes=Uint8Array.from(atob(signature),c=>c.charCodeAt(0));}catch{return reply({error:'unauthorized'},401)}
 const key=await crypto.subtle.importKey('jwk',JSON.parse(env.VERIFY_PUBLIC_KEY),{name:'ECDSA',namedCurve:'P-256'},false,['verify']);
 if(!await crypto.subtle.verify({name:'ECDSA',hash:'SHA-256'},key,bytes,new TextEncoder().encode(raw)))return reply({error:'unauthorized'},401);
 let c;try{c=JSON.parse(raw)}catch{return reply({error:'invalid'},400)}
 if(!keys(c,['domain','action','linkId','version','publicationId','copy','requestId','issuedAt'])||c.domain!=='ipoly-teacher-link-v1'||!hex.test(c.linkId||'')||!hex.test(c.requestId||'')||!Number.isSafeInteger(c.version)||c.version<1||!Number.isSafeInteger(c.issuedAt)||Math.abs(Date.now()-c.issuedAt)>300000||!['publish','disable'].includes(c.action)||c.action==='publish'&&(!hex.test(c.publicationId||'')||!validPortalCopy(c.copy))||c.action==='disable'&&(c.copy!==undefined||c.publicationId!==undefined))return reply({error:'invalid'},400);
 const db=env.DB,hash=await digest(raw),oldRequest=await db.prepare('SELECT hash FROM commands WHERE request_id=?').bind(c.requestId).first();
 if(oldRequest&&oldRequest.hash!==hash)return reply({error:'conflict'},409);
 const existing=await db.prepare('SELECT * FROM teacher_access WHERE id=?').bind(c.linkId).first();
 if(existing&&!existing.enabled)return reply({state:'disabled',linkId:c.linkId,version:existing.version});
 const previous=c.action==='publish'?await db.prepare('SELECT * FROM portal_copies WHERE id=?').bind(c.publicationId).first():null;
 if(previous&&(previous.link_id!==c.linkId||previous.payload!==JSON.stringify(c.copy)))return reply({error:'conflict'},409);
 if(existing&&existing.version>c.version)return reply({state:'superseded',linkId:c.linkId,version:existing.version});
 if(existing&&existing.version===c.version&&(c.action!=='publish'||existing.current_copy_id!==c.publicationId))return reply({error:'conflict'},409);
 const now=Date.now();
 const mutation=c.action==='disable'?db.prepare("INSERT INTO teacher_access(id,version,enabled,updated_at) VALUES(?,?,0,?) ON CONFLICT(id) DO UPDATE SET version=excluded.version,enabled=0,current_copy_id=NULL,updated_at=excluded.updated_at WHERE teacher_access.enabled=1 AND teacher_access.version<excluded.version").bind(c.linkId,c.version,now):db.prepare("INSERT INTO teacher_access(id,version,enabled,teacher_name,shared_by_name,current_copy_id,updated_at) VALUES(?,?,1,?,?,?,?) ON CONFLICT(id) DO UPDATE SET version=excluded.version,teacher_name=excluded.teacher_name,shared_by_name=excluded.shared_by_name,current_copy_id=excluded.current_copy_id,updated_at=excluded.updated_at WHERE teacher_access.enabled=1 AND teacher_access.version<excluded.version").bind(c.linkId,c.version,c.copy.label,c.copy.sharedByName,c.publicationId,now);
 const commands=[db.prepare("INSERT INTO commands(request_id,hash,action,publication_id) VALUES(?,?,?,?) ON CONFLICT(request_id) DO NOTHING").bind(c.requestId,hash,'link:'+c.action,c.publicationId||c.linkId),mutation];
 if(c.action==='publish')commands.push(db.prepare("INSERT INTO portal_copies(id,link_id,payload,published_at,expires_at) SELECT ?,?,?,?,? WHERE EXISTS(SELECT 1 FROM teacher_access WHERE id=? AND version=? AND enabled=1 AND current_copy_id=?) ON CONFLICT(id) DO NOTHING").bind(c.publicationId,c.linkId,JSON.stringify(c.copy),now,now+7*86400000,c.linkId,c.version,c.publicationId));
 await db.batch(commands);
 const link=await db.prepare('SELECT * FROM teacher_access WHERE id=?').bind(c.linkId).first();
 if(!link?.enabled)return reply({state:'disabled',linkId:c.linkId,version:link?.version??c.version});
 const copy=await db.prepare('SELECT * FROM portal_copies WHERE id=?').bind(link.current_copy_id).first();
 return reply({state:link.current_copy_id===c.publicationId?'active':'superseded',linkId:c.linkId,version:link.version,publicationId:link.current_copy_id,publishedAt:copy?.published_at,expiresAt:copy?.expires_at});
}
async function portalRead(id,env){
 if(!hex.test(id))return reply({state:'disabled'},410);
 // Read permission, pointer and immutable copy in one SQLite snapshot.
 const row=await env.DB.prepare('SELECT l.version,l.teacher_name,l.shared_by_name,c.id AS publication_id,c.payload,c.published_at,c.expires_at FROM teacher_access l LEFT JOIN portal_copies c ON c.id=l.current_copy_id AND c.link_id=l.id WHERE l.id=? AND l.enabled=1').bind(id).first();
 if(!row)return reply({state:'disabled'},410);
 const payload=row.payload?JSON.parse(row.payload):null;const profile={teacherName:row.teacher_name,sharedByName:row.shared_by_name,studyLanguage:['sq','en'].includes(payload?.currentLanguage)?payload.currentLanguage:null};
 if(!row.payload||row.expires_at<=Date.now())return reply({state:'empty',profile,version:row.version});
 return reply({state:'ready',profile,version:row.version,publicationId:row.publication_id,publishedAt:row.published_at,expiresAt:row.expires_at,copy:payload});
}

