 const key=await crypto.subtle.importKey('jwk',JSON.parse(env.VERIFY_PUBLIC_KEY),{name:'ECDSA',namedCurve:'P-256'},false,['verify']);if(!await crypto.subtle.verify({name:'ECDSA',hash:'SHA-256'},key,bytes,new TextEncoder().encode(raw)))return reply({error:'unauthorized'},401);
 let c;try{c=JSON.parse(raw)}catch{return reply({error:'invalid'},400)}if(!keys(c,['domain','requestId','issuedAt','action','publicationId','copy','codeHash'])||c.domain!=='ipoly-teacher-copy-v1'||typeof c.requestId!=='string'||!hex.test(c.requestId)||typeof c.publicationId!=='string'||!hex.test(c.publicationId)||!Number.isSafeInteger(c.issuedAt)||Math.abs(Date.now()-c.issuedAt)>300000||!['publish','revoke'].includes(c.action)||c.action==='publish'&&(!validCopy(c.copy)||!hex.test(c.codeHash))||c.action==='revoke'&&(c.copy!==undefined||c.codeHash!==undefined))return reply({error:'invalid'},400);
 const hash=await digest(raw),db=env.DB;const replay=async()=>{const r=await db.prepare('SELECT hash FROM commands WHERE request_id=?').bind(c.requestId).first();if(!r)return null;if(r.hash!==hash)return reply({error:'conflict'},409);const p=await db.prepare('SELECT state,published_at,expires_at FROM copies WHERE id=?').bind(c.publicationId).first();return reply({state:p?.state,publishedAt:p?.published_at,expiresAt:p?.expires_at,replayed:true});};const old=await replay();if(old)return old;
