const viewer=`<!doctype html><html lang="es"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Material para tu clase</title><style>body{font:17px system-ui;max-width:760px;margin:auto;padding:24px;background:#f7f8f3;color:#24332a}input,button{font:inherit;min-height:44px;padding:10px;margin:12px 0;width:100%;box-sizing:border-box}section{padding:18px;border:1px solid #ccd6ce;margin:18px 0}p{white-space:pre-wrap;line-height:1.6}</style><h1>Material para tu clase</h1><p>Solo la copia confirmada. El código no da acceso a la app personal.</p><form id="form"><label>Código de acceso<input id="code" type="password" autocomplete="off" maxlength="32"></label><button>Abrir material</button></form><p id="error" role="alert"></p><main id="material"></main><script>const id=new URL(location.href).searchParams.get('copy'),form=document.getElementById('form'),error=document.getElementById('error'),material=document.getElementById('material');let hasSession=false;const text=(tag,value,parent=material)=>{const el=document.createElement(tag);el.textContent=value;parent.appendChild(el)};let readGeneration=0;async function read(){const generation=++readGeneration;try{const r=await fetch('/api/copies/'+id,{cache:'no-store'}),d=await r.json();if(generation!==readGeneration)return;material.replaceChildren();if(!r.ok)throw Error('Acceso no disponible; consulta al propietario de la clase.');hasSession=true;form.hidden=true;error.textContent='';const c=d.copy;text('h2',c.label);text('p',(c.date||'Sin fecha')+' · '+(c.type||'Sin tipo'));text('p','Idioma previsto: '+c.language+'. Idioma actual: '+c.currentLanguage+'. Sin traducción automática.');c.items.forEach(x=>{const section=document.createElement('section');material.appendChild(section);text('h3',x.label,section);text('p',x.text,section)});}catch(e){if(generation!==readGeneration)return;hasSession=false;form.hidden=false;material.replaceChildren();throw Error(e.message==='Acceso no disponible; consulta al propietario de la clase.'?e.message:'No pudimos verificar el acceso. Comprueba la conexión y vuelve a introducir el código.');}};form.onsubmit=async e=>{e.preventDefault();error.textContent='';try{const r=await fetch('/api/unlock/'+id,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:document.getElementById('code').value.trim().toLowerCase()})});if(!r.ok)throw Error(r.status===429?'Demasiados intentos; espera 15 minutos.':'Código o acceso no disponible.');document.getElementById('code').value='';await read()}catch(e){error.textContent=e.message}};addEventListener('focus',()=>{if(hasSession)read().catch(e=>error.textContent=e.message)});setInterval(()=>{if(hasSession)read().catch(e=>error.textContent=e.message)},15000);if(!/^[a-f0-9]{64}$/.test(id||'')){form.hidden=true;error.textContent='Enlace no disponible.'}else read().catch(()=>{});</script></html>`;

